//! Independent 100-digit HDS-5 inlet-control headwater on sediment-reduced sections, with
//! the face-blocked discharge `(1 - f) Q_0` at each frozen face fraction.
//!
//! `HW` runs up from the bed. Each pair holds the round-down and round-up binary64 bits.

// Generated by `transcribe.py` in `resource/evidence/culvert-blockage/` from its frozen
// `inlet.json`. Regenerate instead of editing.

/// SHA256 of the frozen `inlet.json`.
pub const INLET_SHA256: &str = "4c55773266053a0bc7266825721a323ac3275c2b207e9f0efb2d86aa43b49c9f";

