pub const FACE_FRACTIONS: [u64; 4] = [
    0x0000000000000000,
    0x3fd0000000000000,
    0x3fe0000000000000,
    0x3feccccccccccccd,
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Regime {
    Unsubmerged,
    Transition,
    Submerged,
}

/// One inlet section: its name in `section_rows::SECTIONS` and the reduced full area.
#[derive(Clone, Copy, Debug)]
pub struct InletSection {
    pub name: &'static str,
    pub sediment_depth: u64,
    pub reduced_rise: u64,
    pub reduced_full_area: [u64; 2],
}

/// One code on one inlet section, with the binary64 bits of its coefficients.
#[derive(Clone, Copy, Debug)]
pub struct Code {
    pub section: usize,
    pub code: u32,
    pub form: u32,
    pub mitered: bool,
    pub k: u64,
    pub m: u64,
    pub c: u64,
    pub y: u64,
}

#[derive(Clone, Copy, Debug)]
pub struct Row {
    pub section: usize,
    pub code: u32,
    pub slope: usize,
    pub label: &'static str,
    pub discharge: u64,
    pub regime: Regime,
    pub headwater: [u64; 2],
    pub critical_depth: Option<[u64; 2]>,
    pub blocked_discharge: [[u64; 2]; 4],
}

/// Headwater at the exact limit discharges `X = 3.5` and `X = 4` of one curve.
#[derive(Clone, Copy, Debug)]
pub struct Anchor {
    pub section: usize,
    pub code: u32,
    pub slope: usize,
    pub hw_at_3_5: [u64; 2],
    pub hw_at_4: [u64; 2],
    pub transition_rising: bool,
}

